/**
 * CODEBASE ENGINEERING — LESSON HELPERS
 *
 * CLIENT-SAFE. Builds every terminal in the course from a RECORDED session
 * (./ce-transcripts.js, generated by scripts/ceRecord.mjs), so a lesson can
 * name the commands it wants but can never type an output by hand.
 *
 *   term("m2-find", { goal, accept, near, hint, success })
 *
 * The terminal offers every command recorded in the session, in the order it
 * was run. A session that does not exist throws when the lesson file loads,
 * so a typo fails the build instead of shipping an empty terminal.
 */

import { TRANSCRIPTS } from "./ce-transcripts.js";

/** Git Bash, in the learner's clone of the project. */
export const PROMPT = "ada@laptop:~/kobo-market$";
/** Windows PowerShell, same folder. */
export const PS_PROMPT = "PS C:\\Users\\ada\\kobo-market>";

/** Said once per terminal, so nobody mistakes the normalised paths for a trick. */
const RECORDED = "Recorded from a real run on the Kobo Market project (your home folder is shown as /c/Users/ada).";

export function term(session, spec = {}) {
  const commands = TRANSCRIPTS[session];
  if (!commands) throw new Error(`Codebase Engineering: no recorded session "${session}"`);
  return {
    session,
    prompt: spec.shell === "powershell" ? PS_PROMPT : PROMPT,
    commands,
    available: Object.keys(commands),
    ...spec,
    intro: spec.intro ? `${spec.intro} ${RECORDED}` : RECORDED,
  };
}

/** One recorded output, for quoting in an explanation or example. */
export function out(session, command) {
  const output = TRANSCRIPTS[session]?.[command];
  if (output === undefined) throw new Error(`Codebase Engineering: "${command}" was not recorded in ${session}`);
  return output;
}

/** A recorded command and its output, laid out as it appeared at the prompt. */
export function shown(session, command, prompt = "$") {
  const output = out(session, command);
  return output ? `${prompt} ${command}\n${output}` : `${prompt} ${command}`;
}

export const JS = "javascript";
